border: 1px solid #7f7f7f;
}

.xforms span {
/*display: inline-block;*/
padding-left:3px;
padding-right: 1px;
line-height:22px;
padding-top:0px;
padding-bottom:0px;
text-align:left;
vertical-align:middle;
border: 0px solid #DBDBDB;
}

.xforms.img{
border : 0px;
}

.xforms a:link {

color: #194866;
text-decoration: none;
}
.xforms a:active {

color: #194866;
text-decoration: none;
}
.xforms a:visited {
color: #194866;
text-decoration: none;
}

.xforms A:hover {
color:008BE3;
text-decoration: none;
}

